import {HeaderContainer} from './styles';
import logo from '../../../assets/images/logo.png';

const Header = () =>{
    return(
      <HeaderContainer>
        <div>
          <img src={logo} alt='Logo oppenterprise'/>
        </div>
        <p >Login </p>


      </HeaderContainer>
    )
}

export default Header
